// 1. Autenticación de cabecera obligatoria (O04: Fail-Closed)
const rawInput = $input.first().json || {};
const headers = rawInput.headers || {};
const body = (rawInput.body && typeof rawInput.body === 'object') ? rawInput.body : rawInput;

const expectedSecret = ($env.N8N_WEBHOOK_SECRET || '').trim();
if (!expectedSecret) {
  throw new Error('503 Misconfigured: N8N_WEBHOOK_SECRET is required for WhatsApp dispatch webhook');
}

const headerSecret = (
  headers['x-n8n-webhook-secret'] ||
  headers['X-N8N-Webhook-Secret'] ||
  (headers['authorization'] || headers['Authorization'] || '').replace(/^Bearer\s+/i, '') ||
  ''
).trim();

if (!headerSecret || headerSecret !== expectedSecret) {
  throw new Error('401 Unauthorized: Invalid or missing X-N8N-Webhook-Secret header');
}

// 2. Rechazar campos que intenten sobrescribir URL, instancia ajena o credenciales del proveedor
const forbiddenKeys = ['evolution_url', 'api_key', 'apikey', 'base_url', 'webhook_url'];
for (const k of forbiddenKeys) {
  if (Object.prototype.hasOwnProperty.call(body, k)) {
    throw new Error(`400 Bad Request: Forbidden field '${k}' in dispatch payload`);
  }
}

const allowedInstance = ($env.EVOLUTION_INSTANCE_NAME || 'streamvault').trim();
if (body.instance && String(body.instance).trim() !== allowedInstance) {
  throw new Error('403 Forbidden: Unregistered Evolution instance requested');
}

// 3. Validar destinatario y longitud de mensaje
const rawRecipient = String(body.recipient || body.number || '').trim();
const cleanRecipient = rawRecipient.replace(/[^0-9@._a-zA-Z-]/g, '');
if (!cleanRecipient || cleanRecipient.length < 8 || cleanRecipient.length > 40) {
  throw new Error('400 Bad Request: Invalid recipient format');
}

const messageBody = String(body.message || body.text || '').trim();
if (!messageBody || messageBody.length > 4096) {
  throw new Error('400 Bad Request: Message body must be between 1 and 4096 characters');
}

// 4. Generación de Retardo Gaussiano Humano (mu=67.5s, sigma=15s, acotado entre 45s y 90s)
function gaussianRandom(mean, stdev) {
  let u = 1 - Math.random();
  let v = Math.random();
  let z = Math.sqrt(-2.0 * Math.log(u)) * Math.cos(2.0 * Math.PI * v);
  return mean + z * stdev;
}

const rawDelay = gaussianRandom(67.5, 15.0);
const boundedDelay = Math.round(Math.min(90, Math.max(45, rawDelay)));

return [{
  json: {
    calculated_delay_seconds: boundedDelay,
    enqueued_at: new Date().toISOString(),
    target_recipient: cleanRecipient,
    message_body: messageBody,
    instance_name: allowedInstance,
    idempotency_key: String(body.idempotency_key || '').trim()
  }
}];
